"use client";
import {apiFetch,human,sessionUser,request as serviceRequest} from "./client";

import {useEffect,useMemo,useState} from "react";
import {api} from "./config";
import type {ButtonHTMLAttributes} from "react";
import ProposalEditor from "./ProposalEditor";
import {DocumentInput} from "./DomainWorkspace";

type Row=Record<string,any>;
type Action={kind:string;row?:Row}|null;

const stages=["DISCOVERED","ELIGIBILITY_REVIEW","DIRECTOR_DECISION","ASSIGNED","ACCEPTED","PREPARATION","INTERNAL_REVIEW","INSTITUTIONAL_APPROVAL","SUBMITTED","OUTCOME_RECORDED","AWARDED","CLOSED"];

async function request(path:string,options?:RequestInit){return serviceRequest(path,options)}

function pretty(v:any){return String(v??"").replaceAll("_"," ").toLowerCase().replace(/\b\w/g,c=>c.toUpperCase())}
function date(v:any){if(!v)return "-";const d=new Date(v);return Number.isNaN(d.valueOf())?String(v):d.toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"})}
function money(v:any,c:any){if(v===null||v===undefined)return "-";return `${c||""} ${Number(v).toLocaleString("en-GB",{maximumFractionDigits:2})}`.trim()}
function badge(s:any){const x=String(s??"").toUpperCase();const cls=/APPROVED|PASSED|ELIGIBLE|COMPLETE|ACTIVE|OPEN|SUBMITTED|ACCEPTED/.test(x)?"good":/PENDING|CONDITIONAL|PREPARATION|IN_PROGRESS|REVIEW|NOT_STARTED/.test(x)?"warn":/FAILED|REJECTED|INELIGIBLE|BLOCKED|RETURNED|OVERDUE/.test(x)?"bad":"blue";return <span className={"badge "+cls}>{pretty(s||"Not recorded")}</span>}
function Stat({label,value,note}:{label:string;value:any;note:string}){return <div className="stat"><div className="label">{label}</div><div className="value">{value??0}</div><div className="note">{note}</div></div>}
function Panel({title,sub,children,action}:{title:string;sub?:string;children:any;action?:any}){return <section className="panel"><div className="panelHead"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>}
function Empty({text}:{text:string}){return <div className="empty">{text}</div>}

export default function PreAwardWorkspace({name,primary,refresh,initialApplicationId,onApplicationChange}:{name:string;primary:any;refresh:()=>void;initialApplicationId?:string;onApplicationChange?:(id:string)=>void}){
  const [opportunities,setOpportunities]=useState<Row[]>(Array.isArray(primary)&&name.includes("Opportunity")?primary:[]);
  const [applications,setApplications]=useState<Row[]>(Array.isArray(primary)&&name==="Applications"?primary:[]);
  const [users,setUsers]=useState<Row[]>([]);
  const [researchers,setResearchers]=useState<Row[]>([]);
  const [matches,setMatches]=useState<Row[]>([]);
  const [eois,setEois]=useState<Row[]>([]);
  const [approvals,setApprovals]=useState<Row[]>([]);
  const [discoverySchedule,setDiscoverySchedule]=useState<Row|null>(null);
  const [discoverySources,setDiscoverySources]=useState<Row[]>([]);
  const [discoveryRuns,setDiscoveryRuns]=useState<Row[]>([]);
  const [discoveryEvidence,setDiscoveryEvidence]=useState<Row[]>([]);
  const [selectedAppId,setSelectedAppId]=useState<string>(initialApplicationId||"");
  const [applicationOpened,setApplicationOpened]=useState(Boolean(initialApplicationId));
  const [workspace,setWorkspace]=useState<any>(null);
  const [action,setAction]=useState<Action>(null);
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState("");

  async function loadBase(){
    const [o,a,u,r,m,e,p,ds,dr,de,schedule]=await Promise.all([
      request("/api/opportunities"),
      request("/api/applications"),
      request("/api/admin/users"),
      request("/api/people/researchers"),
      request("/api/opportunity-intelligence/matches"),
      request("/api/pregrant/expressions-of-interest"),
      request("/api/approvals"),
      request("/api/opportunity-intelligence/discovery/sources"),
      request("/api/opportunity-intelligence/discovery/runs?limit=12"),
      request("/api/opportunity-intelligence/discovery/evidence?limit=20"),
      request("/api/opportunity-intelligence/discovery/schedule")
    ]);
    setOpportunities(o);setApplications(a);setUsers(u);setResearchers(r);setMatches(m);setEois(e);setApprovals(p);
    setDiscoverySchedule(schedule);setDiscoverySources(ds);setDiscoveryRuns(dr);setDiscoveryEvidence(de);
    if(!a.some((app:Row)=>app.id===selectedAppId)){if(initialApplicationId){setSelectedAppId("");setMessage("The linked application is unavailable or outside your assigned work.")}else setSelectedAppId(a[0]?.id||"")}
  }
  async function loadWorkspace(id:string){
    if(!id){setWorkspace(null);return}
    setWorkspace(await request("/api/pregrant/applications/"+id+"/workspace"));
  }
  async function reload(){
    setMessage("");
    await loadBase();
    if(selectedAppId)await loadWorkspace(selectedAppId);
    refresh();
  }
  useEffect(()=>{loadBase().catch(e=>setMessage(e.message))},[primary]);
  useEffect(()=>{
    if(name!=="Opportunity Intelligence")return;
    let stopped=false,loading=false;
    const timer=setInterval(async()=>{
      if(loading)return;loading=true;
      try {
        const [o,m,s,r,e,schedule]=await Promise.all(["/api/opportunities","/api/opportunity-intelligence/matches","/api/opportunity-intelligence/discovery/sources","/api/opportunity-intelligence/discovery/runs?limit=12","/api/opportunity-intelligence/discovery/evidence?limit=20","/api/opportunity-intelligence/discovery/schedule"].map(path=>serviceRequest(path,{feedback:false})));
        if(!stopped){setOpportunities(o);setMatches(m);setDiscoverySources(s);setDiscoveryRuns(r);setDiscoveryEvidence(e);setDiscoverySchedule(schedule)}
      }catch{/* Preserve the current view; the next interval retries. */}finally{loading=false}
    },60000);
    return()=>{stopped=true;clearInterval(timer)};
  },[name]);

  useEffect(()=>{let stopped=false;setWorkspace(null);if(selectedAppId&&applications.some(app=>app.id===selectedAppId))request("/api/pregrant/applications/"+selectedAppId+"/workspace").then(r=>{if(!stopped)setWorkspace(r)}).catch(e=>{if(!stopped)setMessage(e.message)});return()=>{stopped=true}},[selectedAppId,applications]);
  useEffect(()=>{if(selectedAppId&&applications.some(app=>app.id===selectedAppId))onApplicationChange?.(selectedAppId)},[selectedAppId,applications]);
  useEffect(()=>{if(applicationOpened)document.getElementById("application-tracking")?.scrollIntoView({behavior:"smooth",block:"start"})},[applicationOpened,selectedAppId]);

  function openAction(a:Action){setMessage("");setAction(a)}
  const selectedApp=applications.find(x=>x.id===selectedAppId)||null;
  const page=(()=>{
    if(name==="Opportunity Intelligence")return <OpportunityIntelligence rows={opportunities} matches={matches} eois={eois} schedule={discoverySchedule} sources={discoverySources} runs={discoveryRuns} evidence={discoveryEvidence} act={openAction} run={run} busy={busy}/>;
    if(name==="Eligibility & Fit")return <Eligibility rows={opportunities} act={openAction}/>;
    if(name==="Applications")return <><Applications rows={applications} act={openAction} select={id=>{setSelectedAppId(id);setApplicationOpened(true)}}/>{applicationOpened&&<section id="application-tracking" className="submission-tracking-summary"><ApplicationHub reloadSelected={()=>loadWorkspace(selectedAppId)} mode="tracking" app={selectedApp} applications={applications} workspace={workspace} select={setSelectedAppId} act={openAction} run={run} users={users} researchers={researchers}/></section>}</>;
    if(name==="Proposal Workspace")return <ApplicationHub reloadSelected={()=>loadWorkspace(selectedAppId)} mode="proposal" app={selectedApp} applications={applications} workspace={workspace} select={setSelectedAppId} act={openAction} run={run} users={users} researchers={researchers}/>;
    if(name==="Budget Builder")return <ApplicationHub reloadSelected={()=>loadWorkspace(selectedAppId)} mode="budget" app={selectedApp} applications={applications} workspace={workspace} select={setSelectedAppId} act={openAction} run={run} users={users} researchers={researchers}/>;
    if(name==="Internal Review")return <ApplicationHub reloadSelected={()=>loadWorkspace(selectedAppId)} mode="review" app={selectedApp} applications={applications} workspace={workspace} select={setSelectedAppId} act={openAction} run={run} users={users} researchers={researchers}/>;
    if(name==="Approvals")return <Approvals rows={initialApplicationId?approvals.filter(r=>r.entity_id===initialApplicationId):approvals} act={openAction}/>;
    if(name==="Submissions")return <><SubmittedApplications applications={applications} select={id=>{setSelectedAppId(id);requestAnimationFrame(()=>document.getElementById("submission-tracking")?.scrollIntoView({behavior:"smooth",block:"start"}))}}/><section id="submission-tracking" className="submission-tracking-summary"><ApplicationHub reloadSelected={()=>loadWorkspace(selectedAppId)} mode="submission" app={selectedApp} applications={applications} workspace={workspace} select={setSelectedAppId} act={openAction} run={run} users={users} researchers={researchers}/></section></>;
    return <Empty text="This pre-award workspace is not configured."/>;
  })();

  async function run(path:string,method:string,body?:any){
    setBusy(true);setMessage("");
    try{await request(path,{method,body:body===undefined?undefined:JSON.stringify(body)});await reload();setMessage("Action completed and the institutional record was updated.");}
    catch(e:any){setMessage(e.message)}
    finally{setBusy(false)}
  }

  return <div className="preawardShell">
    {message&&<div className={message.startsWith("Action completed")?"notice":"notice warn"}>{message}</div>}
    {page}
    {action&&<ActionSheet error={message} action={action} users={users} researchers={researchers} close={()=>setAction(null)} done={async(path,method,body)=>{setBusy(true);setMessage("");try{await request(path,{method,body:JSON.stringify(body)});setAction(null);await reload();setMessage("Action completed and the institutional record was updated.");}catch(e:any){setMessage(e.message)}finally{setBusy(false)}}} busy={busy}/>}
  </div>
}

function OpportunityIntelligence({rows,matches,eois,schedule,sources,runs,evidence,act,run,busy}:{rows:Row[];matches:Row[];eois:Row[];schedule:Row|null;sources:Row[];runs:Row[];evidence:Row[];act:(a:Action)=>void;run:(path:string,method:string,body?:any)=>Promise<void>;busy:boolean}){
  const [search,setSearch]=useState(""),[queuePage,setQueuePage]=useState(0);const filtered=rows.filter(r=>[r.title,r.funder,r.discovery_source_name].some(v=>String(v||"").toLowerCase().includes(search.toLowerCase())));
  const pending=rows.filter(r=>r.discovery_review_status==="PENDING");
  return <><div className="stats"><Stat label="Calls in review queue" value={rows.length} note="Recent calls; see Funding Register for the full collection"/><Stat label="Awaiting human review" value={pending.length} note="External discoveries requiring confirmation"/><Stat label="High institutional fit" value={rows.filter(r=>Number(r.institutional_fit_score)>=85).length} note="Rules-based relevance score"/><Stat label="Active discovery sources" value={sources.filter(s=>s.enabled).length} note="Approved external sources"/></div>
  <Panel title="Automated discovery" sub="Official external sources are fetched on schedule, normalized, deduplicated and retained with source evidence." action={sessionUser()?.roles.some(r=>["DIRECTOR","GRANTS_OFFICER"].includes(r))?<div className="rowActions"><button className="btn" disabled={busy} onClick={()=>run("/api/opportunity-intelligence/fit/recalculate","POST",{})}>Recalculate fit</button><button className="btn primary" disabled={busy} onClick={()=>run("/api/opportunity-intelligence/discovery/run","POST",{})}>{busy?"Running…":"Run discovery now"}</button></div>:undefined}>
    <div className="notice"><strong>Automatic scans: {schedule?.enabled?schedule.label:"Paused"}.</strong> {schedule?.nextRunAt&&<>Next scheduled check: {new Date(schedule.nextRunAt).toLocaleString("en-GB",{timeZone:"Europe/London",timeZoneName:"short"})}. </>}This view refreshes every minute while open. Only enabled sources with their schedule switched on are scanned. New calls receive NHRC fit evidence and remain subject to human eligibility review.</div><div className="sourceGrid">{sources.map(s=><div className="sourceCard" key={human(s.code)}><div><b>{s.name}</b><span>{human(s.code)} · {pretty(s.adapter_type)} · {human(s.trust_level)}</span><span className="tiny">{s.endpoint_url?new URL(s.endpoint_url).hostname:"Source endpoint not configured"}</span></div><div className="sourceActions">{badge(s.enabled?"ACTIVE":"DISABLED")}<span className="tiny">{s.schedule_enabled?"Scheduled":"Schedule paused"}{s.last_success_at?" · Last success "+date(s.last_success_at):""}</span><div className="rowActions">{sessionUser()?.roles.some(r=>["DIRECTOR","GRANTS_OFFICER"].includes(r))&&<><button className="linkbutton" disabled={busy||!s.enabled} onClick={()=>run("/api/opportunity-intelligence/discovery/run","POST",{sourceCode:s.code})}>Run source</button><button className="linkbutton" onClick={()=>run("/api/opportunity-intelligence/discovery/sources/"+s.code,"PATCH",{enabled:!s.enabled})}>{s.enabled?"Disable":"Enable"}</button><button className="linkbutton" onClick={()=>run("/api/opportunity-intelligence/discovery/sources/"+s.code,"PATCH",{scheduleEnabled:!s.schedule_enabled})}>{s.schedule_enabled?"Pause schedule":"Resume schedule"}</button><ActionButton kind="sourceSettings" className="linkbutton" onClick={()=>act({kind:"sourceSettings",row:s})}>Configure</ActionButton></>}</div></div></div>)}</div>
  </Panel>
  <Panel title="Opportunity intelligence review queue" sub="Recent review queue (up to 200 calls). Use Pre-Award, then Funding Register to search and export the complete collection.">
    <div className="filters"><input aria-label="Search recent funding queue" placeholder="Search title, funder or source" value={search} onChange={e=>{setSearch(e.target.value);setQueuePage(0)}}/><span>{filtered.length} matching calls in this queue</span></div><div className="tableWrap" role="region" aria-label="Scrollable records" tabIndex={0}><table><thead><tr><th>Opportunity</th><th>Funder</th><th>Source</th><th>Fit</th><th>Discovery review</th><th>Eligibility</th><th>Deadline</th><th>Actions</th></tr></thead><tbody>{filtered.slice(queuePage*25,(queuePage+1)*25).map(r=><tr key={r.id}><td><b>{r.title}</b><span className="tiny">{/^https?:\/\//.test(r.discovery_external_id||r.source_reference||"")?"External source record":human(r.discovery_external_id||r.source_reference||"")}</span></td><td>{r.funder||"-"}</td><td>{r.discovery_source_name||pretty(r.source_type)}</td><td>{badge((r.institutional_fit_score??"-")+"% fit")}</td><td>{badge(r.discovery_review_status)}</td><td>{badge(r.eligibility_status)}</td><td>{date(r.deadline_at)}</td><td><div className="rowActions">{r.discovery_source_code&&<>{r.discovery_review_status!=="ACCEPTED"&&<ActionButton kind="discoveryReview" className="linkbutton" onClick={()=>act({kind:"discoveryReview",row:{...r,reviewDecision:"ACCEPTED"}})}>Accept discovery</ActionButton>}{r.discovery_review_status!=="REJECTED"&&<ActionButton kind="discoveryReview" className="linkbutton dangerLink" onClick={()=>act({kind:"discoveryReview",row:{...r,reviewDecision:"REJECTED"}})}>Reject</ActionButton>}</>}<ActionButton kind="fit" className="linkbutton" onClick={()=>act({kind:"fit",row:r})}>Review fit</ActionButton>{(!r.discovery_source_code||r.discovery_review_status==="ACCEPTED")&&<><ActionButton kind="eligibility" className="linkbutton" onClick={()=>act({kind:"eligibility",row:r})}>Eligibility</ActionButton><ActionButton kind="application" className="linkbutton" onClick={()=>act({kind:"application",row:r})}>Register application</ActionButton><ActionButton kind="eoi" className="linkbutton" onClick={()=>act({kind:"eoi",row:r})}>EOI</ActionButton></>}</div></td></tr>)}</tbody></table></div><div className="pagination"><span>{filtered.length?queuePage*25+1:0}-{Math.min((queuePage+1)*25,filtered.length)} of {filtered.length}</span><button className="btn small" disabled={!queuePage} onClick={()=>setQueuePage(p=>p-1)}>Previous queue page</button><button className="btn small" disabled={(queuePage+1)*25>=filtered.length} onClick={()=>setQueuePage(p=>p+1)}>Next queue page</button></div>
  </Panel>
  <div className="grid"><Panel title="Latest discovery runs" sub="Every source run records fetched, created, updated, duplicate and rejected counts.">{runs.length?runs.map(r=><div className="item" key={r.id}><div><div className="itemtitle">{r.source_name||r.source_code}</div><div className="itemmeta">{date(r.started_at)} · fetched {r.fetched_count} · created {r.created_count} · updated {r.updated_count} · rejected {r.rejected_count}</div></div>{badge(r.status)}</div>):<Empty text="No discovery runs recorded yet."/>}</Panel>
  <Panel title="Source evidence" sub="Latest external evidence retained for provenance and audit.">{evidence.length?evidence.slice(0,10).map(e=><div className="item" key={e.id}><div><div className="itemtitle">{e.title||e.external_id}</div><div className="itemmeta">{e.source_name} · {pretty(e.validation_status)} · fetched {date(e.fetched_at)}</div></div>{e.canonical_url?<a className="linkbutton" href={e.canonical_url} target="_blank" rel="noreferrer">Source</a>:badge(e.source_status)}</div>):<Empty text="No source evidence recorded yet."/>}</Panel></div>
  <div className="grid"><Panel title="Researcher matching" sub="Explainable rules-based suggestions; human confirmation remains required.">{matches.length?matches.slice(0,8).map(m=><div className="item" key={m.opportunity_id+"-"+m.researcher_profile_id}><div><div className="itemtitle">{m.researcher}</div><div className="itemmeta">{m.opportunity_title} · {m.rationale||"No rationale recorded"}</div></div><div className="rowActions">{badge((m.fit_score??"-")+"% fit")}{badge(m.human_confirmed?"CONFIRMED":"UNCONFIRMED")}<ActionButton kind="matchConfirmation" className="linkbutton" onClick={()=>act({kind:"matchConfirmation",row:{...m,confirmDecision:!m.human_confirmed}})}>{m.human_confirmed?"Unconfirm":"Confirm match"}</ActionButton></div></div>):<Empty text="No researcher matches are recorded yet."/>}</Panel>
  <Panel title="Expression of interest register" sub="Researcher interest is retained before full proposal registration.">{eois.length?eois.slice(0,8).map(e=><div className="item" key={e.id}><div><div className="itemtitle">{e.researcher}</div><div className="itemmeta">{e.opportunity} · {pretty(e.proposed_role)}</div></div>{badge(e.status)}</div>):<Empty text="No expressions of interest recorded."/>}</Panel></div></>
}

function Eligibility({rows,act}:{rows:Row[];act:(a:Action)=>void}){
 return <><div className="stats"><Stat label="Awaiting review" value={rows.filter(r=>!r.eligibility_status||["NOT_REVIEWED","PENDING"].includes(r.eligibility_status)).length} note="Human decision required"/><Stat label="Eligible" value={rows.filter(r=>r.eligibility_status==="ELIGIBLE").length} note="Hard checks passed"/><Stat label="Conditional" value={rows.filter(r=>r.eligibility_status==="CONDITIONAL").length} note="Conditions require resolution"/><Stat label="Ineligible" value={rows.filter(r=>r.eligibility_status==="INELIGIBLE").length} note="Retained for institutional history"/></div>
 <div className="grid"><Panel title="Eligibility and fit queue" sub="Hard funder eligibility remains distinct from strategic relevance.">{rows.map(r=><div className="item" key={r.id}><div><div className="itemtitle">{r.title}</div><div className="itemmeta">{r.funder||"No funder recorded"} · Deadline {date(r.deadline_at)}</div></div><div className="rowActions">{badge(r.eligibility_status)}<ActionButton kind="eligibility" className="btn small" onClick={()=>act({kind:"eligibility",row:r})}>Review</ActionButton></div></div>)}</Panel>
 <Panel title="Assessment controls" sub="The approved NHRC gate before proposal effort is committed."><div className="checks"><p><strong>Institutional eligibility</strong>Organisation type, geography and scheme restrictions.</p><p><strong>Applicant eligibility</strong>Career stage, role and applicant-specific requirements.</p><p><strong>Funding requirements</strong>Ceilings, eligible costs, indirect costs and currency rules.</p><p><strong>Submission requirements</strong>Documents, portal steps and internal deadlines.</p><p><strong>Human confirmation</strong>Fit scores assist review; they do not override funder rules.</p></div></Panel></div></>
}

function Applications({rows,act,select}:{rows:Row[];act:(a:Action)=>void;select:(id:string)=>void}){
 const cols=["ASSIGNED","PREPARATION","INTERNAL_REVIEW","SUBMITTED"];
 return <><div className="stats"><Stat label="Tracked applications" value={rows.length} note="One institutional pre-grant register"/><Stat label="In preparation" value={rows.filter(r=>r.stage==="PREPARATION").length} note="Proposal development"/><Stat label="Internal review" value={rows.filter(r=>r.stage==="INTERNAL_REVIEW").length} note="Controlled review gate"/><Stat label="Submitted" value={rows.filter(r=>r.stage==="SUBMITTED").length} note="Funder outcome tracking"/></div>
 <div className="flow">{cols.map(st=><section className="flowbox" key={st}><h2>{pretty(st)}</h2><div className="flowcount">{rows.filter(r=>r.stage===st).length}</div>{rows.filter(r=>r.stage===st).map(r=><button className="recordCard" key={r.id} onClick={()=>select(r.id)}><b>{r.title}</b><span>{r.reference}</span><em>{r.progress_percent}% progress · {date(r.deadline_at)}</em></button>)}</section>)}</div>
 <Panel title="Full institutional application register" sub="Every proposed application receives a reference and remains in institutional history."><div className="tableWrap" role="region" aria-label="Scrollable records" tabIndex={0}><table><thead><tr><th>Reference</th><th>Application</th><th>Lead researcher</th><th>Stage</th><th>Progress</th><th>Deadline</th><th>Action</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.reference}</td><td><b>{r.title}</b></td><td>{r.lead_researcher||"-"}</td><td>{badge(r.stage)}</td><td>{r.progress_percent}%</td><td>{date(r.deadline_at)}</td><td><button className="linkbutton" onClick={()=>select(r.id)}>Track application</button></td></tr>)}</tbody></table></div></Panel></>
}


function SubmittedApplications({applications,select}:{applications:Row[];select:(id:string)=>void}){
 const[q,setQ]=useState("");
 const submitted=applications.filter(a=>["SUBMITTED","OUTCOME_RECORDED","AWARDED"].includes(a.stage)||["AWARDED","UNSUCCESSFUL","WITHDRAWN"].includes(a.funder_outcome));
 const rows=submitted.filter(a=>`${a.reference} ${a.title} ${a.lead_researcher||""} ${a.funder_outcome||""}`.toLowerCase().includes(q.toLowerCase()));
 return <Panel title="Submitted applications" sub="Recorded submissions and funder outcomes. Open an application to inspect its stages and retained history."><div className="filters"><input aria-label="Search submitted applications" placeholder="Search reference, project or researcher" value={q} onChange={e=>setQ(e.target.value)}/><span>{rows.length} recorded submissions</span></div>{rows.length?<div className="tableWrap" role="region" aria-label="Submitted applications" tabIndex={0}><table><thead><tr><th>Reference</th><th>Application</th><th>Lead researcher</th><th>Current stage</th><th>Funder outcome</th><th>Tracking</th></tr></thead><tbody>{rows.map(a=><tr key={a.id}><td>{a.reference}</td><td>{a.title}</td><td>{a.lead_researcher||"Not assigned"}</td><td>{badge(a.stage)}</td><td>{pretty(a.funder_outcome||"Pending")}</td><td><button className="linkbutton" onClick={()=>select(a.id)}>View stages and history</button></td></tr>)}</tbody></table></div>:<Empty text={q?"No submitted application matches this search.":"No submitted applications have been recorded yet."}/>}</Panel>
}

function AppSelector({applications,value,onChange}:{applications:Row[];value:string;onChange:(v:string)=>void}){return <div className="filters"><div className="field"><label htmlFor="application-selector">Application</label><select id="application-selector" value={value} onChange={e=>onChange(e.target.value)}>{applications.map(a=><option key={a.id} value={a.id}>{a.reference} · {a.title}</option>)}</select></div></div>}

function ApplicationHub({reloadSelected,mode,app,applications,workspace,select,act,run,users,researchers}:{reloadSelected:()=>void;mode:string;app:Row|null;applications:Row[];workspace:any;select:(id:string)=>void;act:(a:Action)=>void;run:(path:string,method:string,body?:any)=>Promise<void>;users:Row[];researchers:Row[]}){
 if(!app)return <section className="panel"><h3>No application selected</h3><p>Register an application from a reviewed funding opportunity, then select it here to develop its proposal, budget and internal reviews.</p></section>;
 if(!workspace||String(workspace.application?.id)!==String(app.id))return <><AppSelector applications={applications} value={app.id} onChange={select}/><section className="panel" role="status">Loading saved application details, decisions and history…</section></>;
 const w=workspace||{};const reqs:wRow[]=[...(w.requirements||[])].sort((a,b)=>String(a.title).localeCompare(String(b.title)));const quality:wRow[]=[...(w.qualityChecks||[])].sort((a,b)=>String(a.title).localeCompare(String(b.title)));const reviews:wRow[]=w.reviews||[];const budget:wRow[]=w.budget||[];const docs:wRow[]=w.documents||[];const team:wRow[]=w.team||[];const portals:wRow[]=w.portals||[];const comms:wRow[]=w.communications||[];const assignments:wRow[]=w.assignments||[];
 const decisions:Row[]=w.approvals||[];const directorDecision=decisions.find(d=>d.approval_type==="DIRECTOR_DECISION"),institutionalDecision=decisions.find(d=>d.approval_type==="INSTITUTIONAL");
 const reached=new Set((w.stageHistory||[]).flatMap((h:Row)=>[h.from_stage,h.to_stage]).filter(Boolean));
 const current=stages.indexOf(app.stage);const next=current>=0&&current<stages.length-1?stages[current+1]:null;
 return <><AppSelector applications={applications} value={app.id} onChange={select}/><div className="appSummary"><div><span className="eyebrow">{app.reference}</span><h2>{app.title}</h2><p className="subtle">{app.lead_researcher||"Lead researcher not assigned"} · deadline {date(app.deadline_at)}</p></div><div className="actions">{badge(app.stage)}{app.stage==="DIRECTOR_DECISION"&&<ActionButton kind="approval" disabled={!workspace||directorDecision?.status==="PENDING"} className="btn" onClick={()=>act({kind:"approval",row:app})}>Request Director decision</ActionButton>}{app.stage==="DIRECTOR_DECISION"?<ActionButton kind="assign" disabled={!workspace||directorDecision?.status!=="APPROVED"} className="btn" onClick={()=>act({kind:"assign",row:app})}>Assign researcher</ActionButton>:app.stage==="ASSIGNED"&&assignments.find(a=>a.response==="PENDING")?<ActionButton kind="assignmentResponse" className="btn" onClick={()=>act({kind:"assignmentResponse",row:{...app,assignmentId:assignments.find(a=>a.response==="PENDING")?.id}})}>Researcher response</ActionButton>:next&&!["INSTITUTIONAL_APPROVAL","SUBMITTED","OUTCOME_RECORDED","AWARDED","CLOSED"].includes(app.stage)&&<ActionButton kind={app.stage==="ACCEPTED"||app.stage==="PREPARATION"?"authorAdvance":"advance"} className="btn" onClick={()=>act({kind:"advance",row:app})}>Advance workflow</ActionButton>}</div></div>
 {decisions.length>0&&<Panel title="Application decisions and revision requests" sub="Decision reasons stay with the application. A newer decision replaces earlier authorisation; approval authority remains with the assigned officer.">{decisions.map((d,i)=><div className="item" key={d.id}><div><div className="itemtitle">{pretty(d.approval_type)}{decisions.find(x=>x.approval_type===d.approval_type)?.id===d.id?" - Latest decision":" - Earlier decision"}</div><div className="itemmeta">{d.decided_by_name||d.assigned_user_name||"Assigned authority"} · {date(d.decided_at||d.created_at)}</div><p>{d.decision_note||"Awaiting the assigned officer's decision."}</p></div>{badge(d.status)}</div>)}{app.stage==="DIRECTOR_DECISION"&&directorDecision?.status!=="APPROVED"&&<p className="notice warn">{directorDecision?.status==="RETURNED"?"Address the return reason, then request a new Director decision.":directorDecision?.status==="REJECTED"?"The Director rejected this request. Assignment is blocked unless a new decision is requested and approved.":"Assignment is blocked until the current Director decision is approved."}</p>}</Panel>}
 <Panel title="Governed pre-award lifecycle" sub="Every gate is retained separately in the application history."><div className="pipeline">{stages.map((s,i)=><div className={"step "+(i===current?"current":reached.has(s)?"done":"")} key={s}><span className="n">{i+1}</span><b>{pretty(s)}</b><small>{i===current?"Current stage":reached.has(s)?"Recorded stage":"No transition recorded"}</small></div>)}</div></Panel>
 {mode==="proposal"&&<><ProposalEditor key={app.id} applicationId={app.id} documents={docs} onSaved={reloadSelected}/><div className="stats"><Stat label="Requirements complete" value={reqs.filter(r=>["COMPLETE","NOT_APPLICABLE"].includes(r.status)).length+"/"+reqs.length} note="Application checklist"/><Stat label="Team members" value={team.length} note="PI, Co-I, partner and collaborator roles"/><Stat label="Controlled documents" value={docs.length} note="Versioned application records"/><Stat label="Portal records" value={portals.length} note="Funder portal tracking"/></div>
 <div className="grid"><Panel title="Application requirements checklist" sub="Documents, institutional information, CVs, letters, approvals and certifications." action={<ActionButton kind="team" className="btn small" onClick={()=>act({kind:"team",row:app})}>Add team member</ActionButton>}>{reqs.map(r=><div className="item" key={r.id}><div><div className="itemtitle">{r.title}</div><div className="itemmeta">{pretty(r.requirement_type)} · {r.owner||"Unassigned"}</div></div><div className="rowActions">{badge(r.status)}<ActionButton kind="requirement" className="linkbutton" onClick={()=>act({kind:"requirement",row:r})}>Review requirement</ActionButton></div></div>)}</Panel>
 <Panel title="Proposal team" sub="Internal and external team roles are recorded against the application.">{team.length?team.map(t=><div className="item" key={t.id}><div><div className="itemtitle">{t.internal_name||t.external_name||"Team member"}</div><div className="itemmeta">{pretty(t.role_code)} · {t.organisation||"NHRC"}</div></div>{badge(t.active?"ACTIVE":"INACTIVE")}</div>):<Empty text="No proposal team members have been added."/>}<ActionButton kind="team" className="btn small" onClick={()=>act({kind:"team",row:app})}>Add team member</ActionButton></Panel></div>
 <div className="grid"><Panel title="Funder portal management" sub="Portal ownership and requirements, without storing passwords.">{portals.length?portals.map(p=><div className="item" key={p.id}><div><div className="itemtitle">{p.portal_name}</div><div className="itemmeta">{p.portal_application_reference||"Reference not recorded"} · {p.owner||"Unassigned"}</div></div>{badge(p.registration_status)}</div>):<Empty text="No funder portal record."/>}<ActionButton kind="portal" className="btn small" onClick={()=>act({kind:"portal",row:app})}>Add portal</ActionButton></Panel>
 <Panel title="Funder communications" sub="Clarifications, additional-information requests and outcome correspondence.">{comms.length?comms.slice(0,6).map(c=><div className="item" key={c.id}><div><div className="itemtitle">{c.subject}</div><div className="itemmeta">{pretty(c.direction)} · {date(c.communication_at)}</div></div>{badge(c.communication_type)}</div>):<Empty text="No funder communication recorded."/>}<ActionButton kind="communication" className="btn small" onClick={()=>act({kind:"communication",row:app})}>Record communication</ActionButton></Panel></div></>}
 {mode==="budget"&&<><div className="stats"><Stat label="Funder request" value={money(budget.reduce((a:number,b:Row)=>a+Number(b.funder_amount||0),0),budget[0]?.currency)} note="Application budget lines"/><Stat label="NHRC contribution" value={money(budget.reduce((a:number,b:Row)=>a+Number(b.nhrc_contribution||0),0),budget[0]?.currency)} note="Institutional contribution"/><Stat label="Partner amount" value={money(budget.reduce((a:number,b:Row)=>a+Number(b.partner_amount||0),0),budget[0]?.currency)} note="Partner share"/><Stat label="Budget lines" value={budget.length} note="Scenario detail"/></div><Panel title="Budget builder" sub="Personnel, activities, equipment, travel, indirect costs, currencies and contributions." action={<ActionButton kind="budget" className="btn primary" onClick={()=>act({kind:"budget",row:app})}>Add budget line</ActionButton>}><div className="tableWrap" role="region" aria-label="Scrollable records" tabIndex={0}><table><thead><tr><th>Category</th><th>Description</th><th>Year</th><th className="num">Quantity</th><th className="num">Unit cost</th><th className="num">Funder</th><th className="num">NHRC</th><th className="num">Partner</th></tr></thead><tbody>{budget.map(b=><tr key={b.id}><td>{b.category}</td><td>{b.description||"-"}</td><td>{b.year_no}</td><td className="num">{b.quantity}</td><td className="num">{money(b.unit_cost,b.currency)}</td><td className="num">{money(b.funder_amount,b.currency)}</td><td className="num">{money(b.nhrc_contribution,b.currency)}</td><td className="num">{money(b.partner_amount,b.currency)}</td></tr>)}</tbody></table></div></Panel></>}
 {mode==="review"&&<><div className="stats"><Stat label="Reviews" value={reviews.length} note="Scientific, Grants, Finance, Legal and Management"/><Stat label="Approved" value={reviews.filter(r=>r.status==="APPROVED").length} note="Completed review gates"/><Stat label="Pending" value={reviews.filter(r=>r.status==="PENDING").length} note="Action required"/><Stat label="Returned" value={reviews.filter(r=>r.status==="RETURNED").length} note="Revision required"/></div><Panel title="Internal review coordination" sub="Review types remain distinct and traceable before institutional approval." action={<div className="rowActions"><ActionButton kind="review" className="btn primary" onClick={()=>act({kind:"review",row:app})}>Add review</ActionButton>{app.stage==="INSTITUTIONAL_APPROVAL"&&<ActionButton kind="approval" className="btn" onClick={()=>act({kind:"approval",row:app})}>Request institutional approval</ActionButton>}</div>}>{reviews.length?reviews.map(r=><div className="item" key={r.id}><div><div className="itemtitle">{pretty(r.review_type)} review</div><div className="itemmeta">{r.reviewer||"Reviewer not assigned"} · {r.comments||"No comment"}</div></div><div className="rowActions">{badge(r.status)}{["PENDING","RETURNED"].includes(r.status)&&r.reviewer_id===sessionUser()?.id&&<><ActionButton kind="reviewDecision" className="linkbutton" onClick={()=>act({kind:"reviewDecision",row:r})}>Record review</ActionButton></>}</div></div>):<Empty text="No internal reviews recorded."/>}</Panel></>}
 {mode==="review"&&(w.reviewHistory||[]).length>0&&<Panel title="Review decision history" sub="Earlier findings are retained when the assigned reviewer records a new decision.">{w.reviewHistory.map((h:Row)=><div className="history-item" key={h.id}><b>{pretty(h.review_type)}: {pretty(h.previous_status)} to {pretty(h.status)}</b><span>{h.actor} · {date(h.occurred_at)}</span><p>{h.note}</p></div>)}</Panel>}
 {mode==="submission"&&<><div className="stats"><Stat label="Quality checks passed" value={quality.filter(q=>["PASSED","NOT_APPLICABLE"].includes(q.status)).length+"/"+quality.length} note="Final application quality gate"/><Stat label="Submission status" value={pretty(app.stage)} note="Institutional application stage"/><Stat label="Funder outcome" value={pretty(app.funder_outcome||"Pending")} note="Retained after submission"/><Stat label="Communications" value={comms.length} note="Post-submission correspondence"/></div>
 <div className="grid"><Panel title="Final application quality check" sub="Completeness, consistency, compliance, attachments, approvals and readiness.">{quality.map(q=><div className="item" key={q.id}><div><div className="itemtitle">{q.title}</div><div className="itemmeta">{pretty(q.check_type)}</div></div><div className="rowActions">{badge(q.status)}<ActionButton kind="qualityDecision" className="linkbutton" onClick={()=>act({kind:"qualityDecision",row:q})}>Review quality check</ActionButton></div></div>)}</Panel>
 <Panel title="Submission and outcome" sub="Final submission is blocked until governed readiness conditions are met."><div className="checks"><p><strong>Institutional approval stage</strong>{reached.has("INSTITUTIONAL_APPROVAL")||["INSTITUTIONAL_APPROVAL","SUBMITTED","OUTCOME_RECORDED","AWARDED"].includes(app.stage)?"Reached":"Not recorded"}</p><p><strong>Final quality checks</strong>{quality.every(q=>["PASSED","NOT_APPLICABLE"].includes(q.status))?"Complete":"Incomplete"}</p><p><strong>Submission proof</strong>{workspace?.application?.submission_acknowledgement||"Not recorded"}</p></div><div className="actions"><ActionButton disabled={app.stage!=="INSTITUTIONAL_APPROVAL"||!workspace||institutionalDecision?.status!=="APPROVED"||decisions.filter((d,i)=>decisions.findIndex(x=>x.approval_type===d.approval_type)===i).some(d=>d.status!=="APPROVED")} kind="submission" className="btn primary" onClick={()=>act({kind:"submission",row:app})}>Record submission</ActionButton><ActionButton disabled={app.stage!=="SUBMITTED"} kind="outcome" className="btn" onClick={()=>act({kind:"outcome",row:app})}>Record outcome</ActionButton>{app.funder_outcome==="AWARDED"&&app.stage==="OUTCOME_RECORDED"&&<ActionButton kind="award" className="btn" onClick={()=>act({kind:"award",row:app})}>Convert to award</ActionButton>}</div></Panel></div></>}
 <div className="grid"><Panel title="Assignment history" sub="Researcher routing and acceptance remain part of the record.">{assignments.length?assignments.map(a=><div className="item" key={a.id}><div><div className="itemtitle">{a.researcher}</div><div className="itemmeta">{date(a.assigned_at)} · {a.response_note||"No response note"}</div></div>{badge(a.response)}</div>):<Empty text="No researcher assignment history."/>}</Panel>
 <Panel title="Stage history" sub="Institutional lifecycle changes are retained.">{(w.stageHistory||[]).map((h:Row)=><div className="item" key={h.id}><div><div className="itemtitle">{pretty(h.from_stage||"Start")} to {pretty(h.to_stage)}</div><div className="itemmeta">{new Date(h.changed_at).toLocaleString("en-GB")} · {h.changed_by_name||"System / unassigned"}</div>{h.note&&<p className="stage-history-note">{human(h.note)}</p>}</div></div>)}</Panel></div></>
}
type wRow=Row;

function Approvals({rows,act}:{rows:Row[];act:(a:Action)=>void}){return <><div className="stats"><Stat label="Awaiting decision" value={rows.filter(r=>r.status==="PENDING").length} note="Institutional decisions"/><Stat label="Approved" value={rows.filter(r=>r.status==="APPROVED").length} note="Completed decisions"/><Stat label="Returned" value={rows.filter(r=>r.status==="RETURNED").length} note="Revision required"/><Stat label="Rejected" value={rows.filter(r=>r.status==="REJECTED").length} note="Closed decisions"/></div><Panel title="Internal decision queue" sub="Requester, assigned authority and decision remain separate."><div className="tableWrap" role="region" aria-label="Scrollable records" tabIndex={0}><table><thead><tr><th>Approval</th><th>Entity</th><th>Requested by</th><th>Assigned to</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{pretty(r.approval_type)}</td><td>{r.entity_reference||pretty(r.entity_type)}{r.entity_title&&<div className="itemmeta">{r.entity_title}</div>}</td><td>{r.requested_by_name||"-"}</td><td>{r.assigned_user_name||human(r.required_role_code)||"Role queue"}</td><td>{badge(r.status)}</td><td>{r.status==="PENDING"&&(!r.assigned_user_id||r.assigned_user_id===sessionUser()?.id)&&(!r.required_role_code||sessionUser()?.roles.includes(r.required_role_code))?<ActionButton kind="approvalDecision" className="linkbutton" onClick={()=>act({kind:"approvalDecision",row:r})}>Review decision</ActionButton>:"-"}</td></tr>)}</tbody></table></div></Panel><div className="notice warn">The requester cannot decide their own approval. Scientific review, Finance clearance, institutional approval and funder decisions remain separate records.</div></>}

function ActionSheet({error,action,users,researchers,close,done,busy}:{error:string;action:NonNullable<Action>;users:Row[];researchers:Row[];close:()=>void;done:(path:string,method:string,body:any)=>Promise<void>;busy:boolean}){
 const [form,setForm]=useState<Record<string,any>>(()=>({...action.row,...(action.kind==="reviewDecision"?{status:"APPROVED"}:action.kind==="qualityDecision"?{status:"PASSED"}:{}),approvalType:action.row?.stage==="DIRECTOR_DECISION"?"DIRECTOR_DECISION":"INSTITUTIONAL"}));
 const row=action.row||{};
 const set=(k:string,v:any)=>setForm(x=>({...x,[k]:v}));
 const input=(label:string,key:string,type="text",required=false)=><label>{label}<input type={type} step={type==="number"?(key==="yearNo"?1:"any"):undefined} min={type==="number"?(key==="yearNo"?1:0):undefined} required={required} value={form[key]??""} onChange={e=>set(key,e.target.value)}/></label>;
 const textarea=(label:string,key:string)=><label>{label}<textarea rows={4} value={form[key]??""} onChange={e=>set(key,e.target.value)}/></label>;
 const userSelect=(label:string,key:string,required=false)=>["actor","assignedBy","requestedBy","decidedBy","recordedBy","confirmedBy","reviewedBy"].includes(key)||(key==="reviewerId"&&action.kind!=="review")?<label>{label}<input readOnly value={sessionUser()?.name||"Signed-in officer"}/></label>:<label>{label}<select aria-label={label} required={required} value={form[key]??""} onChange={e=>set(key,e.target.value)}><option value="">Select</option>{users.map(u=><option key={u.id} value={u.id}>{u.display_name} · {u.roles||u.organisation_unit||"NHRC"}</option>)}</select></label>;
 const researcherSelect=(label:string,key:string)=><label>{label}<select aria-label={label} required value={form[key]??""} onChange={e=>set(key,e.target.value)}><option value="">Select researcher</option>{researchers.filter(r=>r.active&&r.eligible_for_assignment!==false).map(r=><option key={r.id} value={r.researcher_user_id}>{r.display_name} · {r.unit||"NHRC"}</option>)}</select></label>;
 async function submit(e:any){e.preventDefault();let path="",method="POST",body:any={};switch(action.kind){
  case "reviewDecision":path="/api/pregrant/reviews/"+row.id;method="PATCH";body={status:form.status||"APPROVED",reviewerId:sessionUser()?.id,comments:form.comments};break;
  case "qualityDecision":path="/api/pregrant/quality-checks/"+row.id;method="PATCH";body={status:form.status||"PASSED",checkedBy:sessionUser()?.id,note:form.note};break;
  case "requirement":path="/api/pregrant/requirements/"+row.id;method="PATCH";body={status:form.status||row.status,ownerUserId:form.ownerUserId||null,dueAt:form.dueAt?new Date(form.dueAt).toISOString():null,note:form.note||null,evidenceStorageKey:form.evidenceStorageKey||null};break;
  case "sourceSettings":path="/api/opportunity-intelligence/discovery/sources/"+row.code;method="PATCH";body={queryTerms:form.queryTerms||row.query_terms,fetchLimit:Number(form.fetchLimit||row.fetch_limit)};break;
  case "discoveryReview":path="/api/opportunity-intelligence/discovery/opportunities/"+row.id+"/review";body={decision:row.reviewDecision,reviewerId:form.reviewerId,note:form.note||null};break;
  case "matchConfirmation":path="/api/opportunity-intelligence/matches/"+row.opportunity_id+"/"+row.researcher_profile_id+"/confirmation";body={confirmed:Boolean(row.confirmDecision),confirmedBy:form.confirmedBy||null};break;
  case "eligibility":path="/api/opportunities/"+row.id+"/eligibility";body={decision:form.decision||"ELIGIBLE",rationale:form.rationale,conditions:form.conditions||null,reviewedBy:form.actor||null};break;
  case "fit":path="/api/opportunities/"+row.id+"/fit";method="PATCH";body={score:Number(form.score||0),rationale:form.rationale||null,reviewedBy:form.reviewedBy||null};break;
  case "application":path="/api/applications";body={opportunityId:row.id,title:form.title||row.title,deadlineAt:row.deadline_at||null,ownerUserId:form.actor||null};break;
  case "eoi":path="/api/pregrant/expressions-of-interest";body={opportunityId:row.id,researcherId:form.researcherId,proposedRole:form.proposedRole||"PI",teamSummary:form.teamSummary||null,note:form.note||null};break;
  case "team":path="/api/pregrant/applications/"+row.id+"/team";body={userId:form.userId||null,externalName:form.externalName||null,externalEmail:form.externalEmail||null,organisation:form.organisation||null,roleCode:form.roleCode||"CO_INVESTIGATOR",responsibility:form.responsibility||null};break;
  case "assign":path="/api/applications/"+row.id+"/assignments";body={researcherId:form.researcherId,assignedBy:form.assignedBy||null};break;
  case "assignmentResponse":path="/api/applications/assignments/"+row.assignmentId+"/response";body={response:form.response||"ACCEPTED",note:form.note||null};break;
  case "budget":path="/api/proposals/"+row.id+"/budget";body={category:form.category,description:form.description||null,yearNo:Number(form.yearNo||1),quantity:Number(form.quantity||1),unitCost:Number(form.unitCost||0),currency:(form.currency||"GBP").toUpperCase(),funderAmount:Number(form.funderAmount||0),nhrcContribution:Number(form.nhrcContribution||0),partnerAmount:Number(form.partnerAmount||0)};break;
  case "review":path="/api/proposals/"+row.id+"/reviews";body={reviewType:form.reviewType||"SCIENTIFIC",reviewerId:form.reviewerId||null,comments:form.comments||null};break;
  case "portal":path="/api/pregrant/applications/"+row.id+"/portals";body={portalName:form.portalName,portalUrl:form.portalUrl||null,portalApplicationReference:form.portalRef||null,ownerUserId:form.ownerUserId||null,portalDeadlineAt:form.portalDeadline?new Date(form.portalDeadline).toISOString():null,requirementsNote:form.requirementsNote||null};break;
  case "communication":path="/api/pregrant/applications/"+row.id+"/communications";body={communicationType:form.communicationType||"CLARIFICATION",direction:form.direction||"INBOUND",subject:form.subject,communicationAt:form.communicationAt?new Date(form.communicationAt).toISOString():new Date().toISOString(),contactName:form.contactName||null,contactEmail:form.contactEmail||null,summary:form.summary||null,recordedBy:form.recordedBy||null};break;
  case "advance":{const i=stages.indexOf(row.stage);const next=i>=0&&i<stages.length-1?stages[i+1]:null;if(!next)return;path="/api/applications/"+row.id+"/stage";body={stage:next,note:form.note||"Workflow advanced in UAT",actorId:form.actor||null};break}
  case "approval":path="/api/approvals";body={entityType:"APPLICATION",entityId:row.id,approvalType:form.approvalType||"INSTITUTIONAL",assignedUserId:form.assignedUserId||null,requestedBy:form.requestedBy||null};break;
  case "approvalDecision":path="/api/approvals/"+row.id+"/decision";body={decision:form.decision||"APPROVED",decidedBy:form.decidedBy||null,note:form.note||null};break;
  case "submission":path="/api/pregrant/applications/"+row.id+"/submission";body={submittedAt:new Date().toISOString(),acknowledgement:form.acknowledgement||null,proofStorageKey:form.proofStorageKey||null};break;
  case "outcome":path="/api/applications/"+row.id+"/outcome";body={outcome:form.outcome||"AWARDED"};break;
  case "award":path="/api/applications/"+row.id+"/convert-to-award";body={reference:form.reference,startDate:form.startDate||null,endDate:form.endDate||null,currency:(form.currency||"GBP").toUpperCase(),totalAward:Number(form.totalAward||0),nhrcAllocation:Number(form.nhrcAllocation||0),partnerAllocation:Number(form.partnerAllocation||0)};break;
  default:return}
  await done(path,method,body)
 }
 const title:{[k:string]:string}={reviewDecision:"Record internal review",qualityDecision:"Record final quality check",requirement:"Review application requirement",sourceSettings:"Configure discovery source",discoveryReview:"Review discovered opportunity",matchConfirmation:"Confirm researcher match",eligibility:"Record eligibility decision",fit:"Review institutional fit",application:"Register application",eoi:"Researcher/team expression of interest",team:"Add proposal team member",assign:"Assign researcher",assignmentResponse:"Researcher assignment response",budget:"Add budget line",review:"Add internal review",portal:"Add funder portal record",communication:"Record funder communication",advance:"Advance application workflow",approval:"Request institutional approval",approvalDecision:"Record approval decision",submission:"Record grant submission",outcome:"Record funder outcome",award:"Convert successful application to award"};
 return <div className="drawerBackdrop"><aside className="drawer actionDrawer" role="dialog" aria-modal="true" onClick={e=>e.stopPropagation()}><button className="close" data-dialog-close aria-label="Close application action" onClick={close}>Close</button><span className="eyebrow">CONTROLLED ACTION</span><h2>{title[action.kind]||"Application action"}</h2><p className="subtle">{row.title||row.application_title||row.reference||""}</p><form className="form" onSubmit={submit}>{error&&<div className="feedback error" role="alert">{error}</div>}
 {action.kind==="reviewDecision"&&<><label>Review decision<select aria-label="Review decision" value={form.status||"APPROVED"} onChange={e=>set("status",e.target.value)}>{["APPROVED","RETURNED","REJECTED"].map(s=><option value={s} key={s}>{human(s)}</option>)}</select></label>{textarea("Scientific or functional review findings and decision reason","comments")}<p className="field-help">Recorded by {sessionUser()?.name}. Only the assigned reviewer can decide this review.</p></>}{action.kind==="qualityDecision"&&<><label>Quality decision<select aria-label="Quality decision" value={form.status||"PASSED"} onChange={e=>set("status",e.target.value)}>{["PASSED","FAILED","NOT_APPLICABLE"].map(s=><option value={s} key={s}>{human(s)}</option>)}</select></label>{textarea("Evidence checked and decision rationale","note")}</>}{action.kind==="requirement"&&<><label>Checklist status<select aria-label="Checklist status" value={form.status||row.status} onChange={e=>set("status",e.target.value)}>{["NOT_STARTED","IN_PROGRESS","COMPLETE","NOT_APPLICABLE","BLOCKED"].map(s=><option value={s} key={s}>{human(s)}</option>)}</select></label>{userSelect("Responsible owner","ownerUserId")}{input("Internal due date","dueAt","datetime-local")}{textarea("Sponsor requirement, review note and completion evidence","note")}<DocumentInput label="Requirement evidence" value={form.evidenceStorageKey||""} onChange={v=>set("evidenceStorageKey",v)}/></>}{action.kind==="discoveryReview"&&<>{userSelect("Reviewed by","reviewerId",true)}{textarea("Decision note","note")}<div className={row.reviewDecision==="REJECTED"?"notice warn":"notice"}>Decision: <b>{pretty(row.reviewDecision)}</b>. This records the human NHRC review before downstream eligibility, EOI or application registration.</div></>}
 {action.kind==="matchConfirmation"&&<>{userSelect("Confirmed by","confirmedBy",Boolean(row.confirmDecision))}<div className="notice">Researcher: <b>{row.researcher||"Selected researcher"}</b><br/>Suggested fit: <b>{row.fit_score??"-"}%</b><br/>{row.rationale||"No automated rationale recorded."}</div></>}
 {action.kind==="sourceSettings"&&<><label>Discovery terms<textarea rows={5} placeholder={row.query_terms||"term|term|term"} value={form.queryTerms??""} onChange={e=>set("queryTerms",e.target.value)}/></label><label>Maximum records per run<input type="number" min="1" max="500" placeholder={String(row.fetch_limit||25)} value={form.fetchLimit??""} onChange={e=>set("fetchLimit",e.target.value)}/></label><div className="notice">Use a vertical bar (|) between search terms. Endpoints are governed by the platform and cannot be changed from this screen.</div></>}
 {action.kind==="fit"&&<><div className="notice"><b>Automated institutional fit</b><br/>Score: {row.automated_fit_score??row.institutional_fit_score??"-"}% · Model: {human(row.fit_model_version||"Not yet assessed")}<br/>{row.automated_fit_rationale||row.fit_rationale||"No automated rationale recorded."}</div>{input("Human-reviewed fit score (%)","score","number",true)}{textarea("Human review rationale","rationale")}{userSelect("Reviewed by","reviewedBy",true)}</>}
 {action.kind==="eligibility"&&<><label>Decision<select aria-label="Decision" value={form.decision||"ELIGIBLE"} onChange={e=>set("decision",e.target.value)}><option value="ELIGIBLE">Eligible</option><option value="CONDITIONAL">Conditional</option><option value="INELIGIBLE">Ineligible</option></select></label>{textarea("Rationale","rationale")}{textarea("Conditions, if any","conditions")}{userSelect("Reviewed by","actor")}</>}
 {action.kind==="application"&&<>{input("Application title","title","text",false)}{userSelect("Grants owner","actor")}</>}
 {action.kind==="eoi"&&<>{researcherSelect("Researcher","researcherId")}<label>Proposed role<select aria-label="Proposed role" value={form.proposedRole||"PI"} onChange={e=>set("proposedRole",e.target.value)}><option value="PI">Principal Investigator</option><option value="CO_PI">Co-PI</option><option value="CO_INVESTIGATOR">Co-Investigator</option><option value="TEAM_MEMBER">Team Member</option></select></label>{textarea("Proposed team / collaboration","teamSummary")}{textarea("Note","note")}</>}
 {action.kind==="assign"&&<>{researcherSelect("Researcher","researcherId")}{userSelect("Assigned by","assignedBy")}</>}
 {action.kind==="assignmentResponse"&&<><label>Response<select aria-label="Response" value={form.response||"ACCEPTED"} onChange={e=>set("response",e.target.value)}><option value="ACCEPTED">Accepted</option><option value="DECLINED">Declined</option></select></label>{textarea("Response note","note")}</>}
 {action.kind==="team"&&<>{userSelect("Internal NHRC user","userId")}{input("External member name","externalName")}{input("External email","externalEmail","email")}{input("Organisation","organisation")}<label>Role<select aria-label="Role" value={form.roleCode||"CO_INVESTIGATOR"} onChange={e=>set("roleCode",e.target.value)}><option value="PI">PI</option><option value="CO_PI">Co-PI</option><option value="CO_INVESTIGATOR">Co-Investigator</option><option value="COLLABORATOR">Collaborator</option><option value="CONSULTANT">Consultant</option><option value="PARTNER">Partner representative</option></select></label>{textarea("Responsibility","responsibility")}</>}
 {action.kind==="budget"&&<>{input("Category","category","text",true)}{textarea("Description","description")}{input("Year","yearNo","number")}{input("Quantity","quantity","number")}{input("Unit cost","unitCost","number")} {input("Currency","currency","text")}{input("Funder amount","funderAmount","number")}{input("NHRC contribution","nhrcContribution","number")}{input("Partner amount","partnerAmount","number")}</>}
 {action.kind==="review"&&<><label>Review type<select aria-label="Review type" value={form.reviewType||"SCIENTIFIC"} onChange={e=>set("reviewType",e.target.value)}><option value="SCIENTIFIC">Scientific</option><option value="ADMINISTRATIVE">Administrative</option><option value="FINANCE">Finance</option><option value="LEGAL">Legal</option><option value="MANAGEMENT">Management</option><option value="GRANTS">Grants</option></select></label>{userSelect("Reviewer","reviewerId")}{textarea("Instructions / comments","comments")}</>}
 {action.kind==="portal"&&<>{input("Portal name","portalName","text",true)}{input("Portal URL","portalUrl","url")}{input("Portal application reference","portalRef")}{userSelect("Portal owner","ownerUserId")}{input("Portal deadline","portalDeadline","datetime-local")}{textarea("Portal-specific requirements","requirementsNote")}</>}
 {action.kind==="communication"&&<><label>Direction<select aria-label="Direction" value={form.direction||"INBOUND"} onChange={e=>set("direction",e.target.value)}><option value="INBOUND">Inbound</option><option value="OUTBOUND">Outbound</option></select></label>{input("Communication type","communicationType")}{input("Subject","subject","text",true)}{input("Date/time","communicationAt","datetime-local")}{input("Funder contact","contactName")}{input("Contact email","contactEmail","email")}{textarea("Summary","summary")}{userSelect("Recorded by","recordedBy")}</>}
 {action.kind==="advance"&&<>{userSelect("Actor","actor")}{textarea("Workflow note","note")}<div className="notice">Current stage: <b>{pretty(row.stage)}</b>. The next governed stage is <b>{pretty(stages[stages.indexOf(row.stage)+1]||"End")}</b>.</div></>}
 {action.kind==="approval"&&<><label>Decision requested<select aria-label="Decision requested" value={form.approvalType||"INSTITUTIONAL"} onChange={e=>set("approvalType",e.target.value)}>{["DIRECTOR_DECISION","INSTITUTIONAL","FINANCE_CLEARANCE"].map(s=><option value={s} key={s}>{human(s)}</option>)}</select></label>{userSelect("Assigned approver","assignedUserId")}{userSelect("Requested by","requestedBy")}</>}
 {action.kind==="approvalDecision"&&<><label>Decision<select aria-label="Decision" value={form.decision||"APPROVED"} onChange={e=>set("decision",e.target.value)}><option value="APPROVED">Approved</option><option value="RETURNED">Returned</option><option value="REJECTED">Rejected</option></select></label>{userSelect("Decision made by","decidedBy",true)}{textarea("Decision note","note")}</>}
 {action.kind==="submission"&&<>{input("Submission acknowledgement / receipt","acknowledgement")}<DocumentInput label="Submission proof" value={form.proofStorageKey||""} onChange={v=>set("proofStorageKey",v)}/><div className="notice warn">Submission is accepted only after institutional approval, completed quality checks and no pending application approval.</div></>}
 {action.kind==="outcome"&&<><label>Funder outcome<select aria-label="Funder outcome" value={form.outcome||"AWARDED"} onChange={e=>set("outcome",e.target.value)}><option value="AWARDED">Awarded</option><option value="UNSUCCESSFUL">Unsuccessful</option><option value="WITHDRAWN">Withdrawn</option></select></label></>}
 {action.kind==="award"&&<>{input("Award reference","reference","text",true)}{input("Start date","startDate","date")}{input("End date","endDate","date")}{input("Currency","currency","text",true)}{input("Total award","totalAward","number",true)}{input("NHRC allocation","nhrcAllocation","number",true)}{input("Partner allocation","partnerAllocation","number")}</>}
 <div className="actions"><button type="button" className="btn" onClick={close}>Cancel</button><button className="btn primary" disabled={busy}>{busy?"Saving…":title[action.kind]||"Save changes"}</button></div></form></aside></div>
}

function ActionButton({kind,...props}:{kind:string}&ButtonHTMLAttributes<HTMLButtonElement>){const roles=sessionUser()?.roles||[];const allowed=kind==="approvalDecision"?roles.some(r=>["DIRECTOR","FINANCE_APPROVER"].includes(r)):kind==="reviewDecision"?roles.some(r=>["RESEARCHER","DIRECTOR","FINANCE_OFFICER","FINANCE_APPROVER"].includes(r)):kind==="authorAdvance"?roles.some(r=>["GRANTS_OFFICER","RESEARCHER"].includes(r)):kind==="eoi"||kind==="assignmentResponse"?roles.includes("RESEARCHER"):kind==="qualityDecision"||["advance","sourceSettings","discoveryReview","matchConfirmation","eligibility","fit","application","assign","review","approval","submission","outcome","award"].includes(kind)?roles.includes("GRANTS_OFFICER"):roles.some(r=>["GRANTS_OFFICER","RESEARCHER","DIRECTOR","FINANCE_OFFICER"].includes(r));return allowed?<button {...props}/>:null}
